typedef struct arm64_scheduler_cpu_runtime {
    uint64_t kernel_resume_sp;
    uint64_t task_run_started_us;
    uint64_t kernel_execution_irq_flags;
    uint16_t reschedule_target_plus_one;
    uint16_t fuse_reschedule_target_plus_one;
    uint16_t fuse_reply_target_plus_one;
    uint16_t kernel_execution_depth;
    volatile uint8_t kernel_execution_waiting;
    uint8_t kernel_execution_scheduler_handoffs;
    volatile uint32_t assigned_tasks;
} arm64_scheduler_cpu_runtime_t;

static arm64_scheduler_cpu_runtime_t
    g_arm64_scheduler_cpus[EDGE_SMP_MAX_CPUS];
static volatile uint64_t g_kernel_timer_global_service_us;

static arm64_scheduler_cpu_runtime_t *arm64_scheduler_cpu_local(void) {
    uint32_t cpu = edgeos_arm64_smp_current_cpu();

    if (cpu >= EDGE_SMP_MAX_CPUS) cpu = 0u;
    return &g_arm64_scheduler_cpus[cpu];
}

#define g_kernel_resume_sp \
    (arm64_scheduler_cpu_local()->kernel_resume_sp)
#define g_task_run_started_us \
    (arm64_scheduler_cpu_local()->task_run_started_us)
#define g_reschedule_target_plus_one \
    (arm64_scheduler_cpu_local()->reschedule_target_plus_one)
#define g_fuse_reschedule_target_plus_one \
    (arm64_scheduler_cpu_local()->fuse_reschedule_target_plus_one)
#define g_fuse_reply_target_plus_one \
    (arm64_scheduler_cpu_local()->fuse_reply_target_plus_one)

