static kernel_pipe_t *g_pipes;
static uint32_t g_pipe_capacity = KERNEL_PIPE_MAX;
static uint64_t
    g_pipe_poll_waiters[EDGE_RUNTIME_MAX_PIPES][KERNEL_WAIT_TASK_WORDS];
static uint64_t
    g_socket_poll_waiters[EDGE_RUNTIME_MAX_SOCKETS][KERNEL_WAIT_TASK_WORDS];
