static int g_next_pid = 2;
static edge_pid_index_t g_task_pid_index;
static spinlock_t g_task_lock;
/*
 * The transitional ARM64 runtime still serializes architecture task state.
 * A test-and-set lock lets a syscall-heavy CPU reacquire indefinitely while
 * CPUs already waiting to deliver input or filesystem progress starve.  A
 * direct CPU handoff provides bounded ownership until those remaining shared
 * structures are converted to finer-grained synchronization.  Unlike a
 * ticket sequence, a handoff cannot strand a reservation when an interrupt
 * temporarily redirects a CPU that was waiting for the runtime.
 */
static volatile uint64_t g_kernel_execution_owner_hardware_plus_one;
static volatile uint8_t g_scheduler_runtime_ready;
static kernel_tty_state_t g_tty_states[ARM64_TTY_PL011_BASE + 16u];
static kernel_pty_t g_ptys[KERNEL_PTY_MAX];
static uint8_t g_pl011_rx[ARM64_PL011_RX_CAPACITY];
static volatile uint32_t g_pl011_rx_head;
static volatile uint32_t g_pl011_rx_tail;
static spinlock_t g_futex_lock;
#define KERNEL_FUTEX_BUCKET_COUNT 256u
static uint16_t g_futex_bucket_heads[KERNEL_FUTEX_BUCKET_COUNT];
static void futex_wait_state_clear(kernel_task_t *task);

static kernel_file_description_locator_t
arm64_description_locator(uint64_t identity) {
    return kernel_file_description_identity_locator(identity);
}

static void arm64_description_detach(void *context, uint64_t identity) {
    (void)context;
    kernel_epoll_detach_description(identity);
}

static void arm64_description_release_path(void *context, void *payload) {
    (void)context;
    if (payload) arch_vm_free_page(payload);
}

static const kernel_file_description_ops_t
    arm64_file_description_ops = {
        .detach_description = arm64_description_detach,
        .release_payload = arm64_description_release_path,
        .context = 0,
    };

static int fd_description_create(bootstrap_fd_t *fd) {
    char *path;
    uint32_t handle = 0;
    uint64_t identity = 0;
    int result;

    if (!fd) return -LINUX_EINVAL;
    path = (char *)arch_vm_alloc_page();
    if (!path) return -LINUX_ENOMEM;
    result = kernel_file_description_create(
        fd->offset, fd->status_flags, path, &handle, &identity);
    if (result < 0) {
        arch_vm_free_page(path);
        return result;
    }
    (void)handle;
    fd->open_description_id = identity;
    fd->path = path;
    return 0;
}

static int arm64_description_release_only(uint64_t identity) {
    kernel_file_description_release_t release;
    int result;

    if (!identity) return -LINUX_EBADF;
    result = kernel_file_description_release_begin(
        arm64_description_locator(identity), &release);
    if (result < 0) return result;
    if (release.active)
        return kernel_file_description_release_finish(&release);
    return 0;
}

static void fd_description_discard(bootstrap_fd_t *fd) {
    if (!fd) return;
    (void)arm64_description_release_only(fd->open_description_id);
    fd->open_description_id = 0;
    fd->path = 0;
}

static uint32_t fd_description_reference_count(uint64_t identity) {
    kernel_file_description_snapshot_t snapshot;

    if (!identity ||
        kernel_file_description_snapshot(
            arm64_description_locator(identity), &snapshot) < 0)
        return 0;
    return snapshot.references;
}

static int arm64_description_status_store(uint64_t identity,
                                          uint32_t status_flags) {
    if (!identity) return -LINUX_EBADF;
    return kernel_file_description_status_update(
        arm64_description_locator(identity), UINT32_MAX, status_flags);
}

static int fd_description_refresh_status(bootstrap_fd_t *fd) {
    uint32_t status_flags;
    int result;

    if (!fd || !fd->open_description_id) return -LINUX_EBADF;
    result = kernel_file_description_status_load(
        arm64_description_locator(fd->open_description_id),
        &status_flags);
    if (result < 0) return result;
    fd->status_flags = status_flags;
    return 0;
}

static void fd_description_mount_initialize(bootstrap_fd_t *fd,
                                            int32_t current_pid) {
    int32_t target_pid;
    uint32_t namespace_id;

    if (!fd || fd->kind != KERNEL_FD_FILE || !fd->open_description_id ||
        !kernel_linux_mount_monitor_target(fd->path, current_pid,
                                           &target_pid) ||
        kernel_process_mount_namespace_id(target_pid, &namespace_id) < 0)
        return;
    (void)kernel_file_description_mount_bind(
        arm64_description_locator(fd->open_description_id),
        namespace_id,
        vfs_mount_namespace_event_generation(namespace_id));
}

static int fd_description_mount_snapshot(
    const bootstrap_fd_t *fd, uint32_t *namespace_id,
    uint32_t *observed_generation) {
    uint32_t ignored_namespace;
    uint32_t ignored_generation;

    if (!fd || fd->kind != KERNEL_FD_FILE || !fd->open_description_id)
        return 0;
    if (!namespace_id) namespace_id = &ignored_namespace;
    if (!observed_generation) observed_generation = &ignored_generation;
    return kernel_file_description_mount_snapshot(
               arm64_description_locator(fd->open_description_id),
               namespace_id, observed_generation) == 0;
}

static int fd_is_mount_event_source(const bootstrap_fd_t *fd) {
    return fd_description_mount_snapshot(fd, 0, 0);
}

static int fd_mount_monitor_pending(const bootstrap_fd_t *fd) {
    uint32_t namespace_id;
    uint32_t observed_generation;
    uint32_t current_generation;

    if (!fd_description_mount_snapshot(
            fd, &namespace_id, &observed_generation))
        return 0;
    current_generation =
        vfs_mount_namespace_event_generation(namespace_id);
    return current_generation != observed_generation;
}

static void fd_mount_monitor_acknowledge(bootstrap_fd_t *fd) {
    uint32_t namespace_id;
    uint32_t observed_generation;

    if (!fd || !fd->open_description_id ||
        !fd_description_mount_snapshot(
            fd, &namespace_id, &observed_generation))
        return;
    (void)observed_generation;
    (void)kernel_file_description_mount_acknowledge(
        arm64_description_locator(fd->open_description_id),
        namespace_id,
        vfs_mount_namespace_event_generation(namespace_id));
}

static uint32_t g_next_files_id = 2;
static uint32_t g_next_fs_id = 2;
static uint32_t g_next_sighand_id = 2;
static kernel_socket_t *g_sockets;
static uint8_t g_socket_slot_claims[KERNEL_SOCKET_MAX];
static kernel_socket_connect_deadline_tracker_t
    g_socket_connect_deadline_tracker;
static uint64_t g_unix_bind_generation = 1;
static volatile uint64_t g_scheduler_cpu_user_us[EDGE_SMP_MAX_CPUS];
static volatile uint64_t g_scheduler_cpu_system_us[EDGE_SMP_MAX_CPUS];
static volatile uint64_t g_scheduler_cpu_wait_us[EDGE_SMP_MAX_CPUS];
static volatile uint64_t g_scheduler_cpu_switches[EDGE_SMP_MAX_CPUS];
static volatile uint64_t g_scheduler_cpu_migrations[EDGE_SMP_MAX_CPUS];
static uint8_t g_raw_ipv4_packet[65535];
static char g_pivot_rebased_path[VFS_PATH_MAX];
static uint8_t g_raw_receive_frame[1600];
static uint64_t g_allocated_vts = 1ULL << 1;
static uint32_t g_loopback_address = 0x0100007fu;
static uint32_t g_loopback_netmask = 0x000000ffu;
static uint32_t g_loopback_flags =
    LINUX_IFF_UP | LINUX_IFF_LOOPBACK | LINUX_IFF_RUNNING;

static uint8_t task_tty_identity(const kernel_task_t *task,
                                 const bootstrap_fd_t *fd) {
    if (fd->tty_identity == KERNEL_TTY_CURRENT && task->has_controlling_tty)
        return task->controlling_tty;
    return fd->tty_identity == KERNEL_TTY_CURRENT ? KERNEL_TTY_CONSOLE : fd->tty_identity;
}

static kernel_tty_state_t *task_tty_state(const kernel_task_t *task,
                                                    const bootstrap_fd_t *fd) {
    uint8_t identity = task_tty_identity(task, fd);
    if (identity >= ARM64_TTY_PL011_BASE + 16u) {
        uint32_t pty_index = identity - (ARM64_TTY_PL011_BASE + 16u);
        return pty_index < KERNEL_PTY_MAX && g_ptys[pty_index].used ?
               &g_ptys[pty_index].tty : 0;
    }
    if (identity >= sizeof(g_tty_states) / sizeof(g_tty_states[0])) return 0;
    return &g_tty_states[identity];
}

static kernel_task_t *current_task(void) {
    uint64_t value;
    if (!g_tasks) return 0;
    uintptr_t first = (uintptr_t)&g_tasks[0];
    uintptr_t last = (uintptr_t)&g_tasks[KERNEL_BOOTSTRAP_MAX_TASKS];
    value = arch_cpu_current_task();
    if (value < first || value >= last ||
        ((value - first) % sizeof(g_tasks[0])) != 0) return 0;
    return (kernel_task_t *)(uintptr_t)value;
}

static void task_scheduler_counter_add(volatile uint64_t *counter,
                                       uint64_t delta) {
    uint64_t old;

    if (!counter || !delta) return;
    old = __atomic_load_n(counter, __ATOMIC_RELAXED);
    for (;;) {
        uint64_t next = old > UINT64_MAX - delta ? UINT64_MAX : old + delta;

        if (__atomic_compare_exchange_n(counter, &old, next, 0,
                                        __ATOMIC_RELAXED,
                                        __ATOMIC_RELAXED))
            return;
    }
}

void edgeos_arm64_kernel_execution_enter(void) {
    arm64_scheduler_cpu_runtime_t *cpu = arm64_scheduler_cpu_local();
    uint64_t owner_hardware_plus_one =
        edgeos_arm64_smp_current_hardware_id() + 1u;
    uint64_t flags;

    if (cpu->kernel_execution_depth) {
        uint64_t owner = __atomic_load_n(
            &g_kernel_execution_owner_hardware_plus_one,
            __ATOMIC_ACQUIRE);

        if (owner == owner_hardware_plus_one) return;
        /*
         * A scheduler handoff can abandon an exception stack.  Never let a
         * stale per-CPU nesting flag stand in for ownership of the global
         * runtime; another CPU may currently own it.
         */
        cpu->kernel_execution_depth = 0u;
        cpu->kernel_execution_irq_flags = 0u;
    }
    __asm__ __volatile__("mrs %0, daif" : "=r"(flags));
    __atomic_store_n(&cpu->kernel_execution_waiting, 1u,
                     __ATOMIC_RELEASE);
    for (;;) {
        uint64_t owner = __atomic_load_n(
            &g_kernel_execution_owner_hardware_plus_one, __ATOMIC_ACQUIRE);

        if (owner == 0u) {
            uint64_t expected = 0u;

            if (__atomic_compare_exchange_n(
                    &g_kernel_execution_owner_hardware_plus_one, &expected,
                    owner_hardware_plus_one, 0, __ATOMIC_ACQUIRE,
                    __ATOMIC_RELAXED))
                break;
        }
        __asm__ __volatile__(
            "msr daifclr, #2\n\tyield\n\tmsr daifset, #2"
            ::: "memory");
    }
    cpu->kernel_execution_irq_flags = flags;
    cpu->kernel_execution_depth = 1u;
    __atomic_store_n(&cpu->kernel_execution_waiting, 0u,
                     __ATOMIC_RELEASE);
    __asm__ __volatile__("msr daif, %0" :: "r"(flags) : "memory");
}

void edgeos_arm64_kernel_execution_enter_from_user(void) {
    arm64_scheduler_cpu_runtime_t *cpu = arm64_scheduler_cpu_local();
    uint64_t owner_hardware_plus_one =
        edgeos_arm64_smp_current_hardware_id() + 1u;
    uint64_t wait_started_us = boottime_monotonic_us();
    uint64_t flags;

    /*
     * An EL0 exception is never a recursive kernel entry.  Acquire by a
     * zero-to-owner transition even when the local depth appears nonzero.
     * This prevents stale or aliased per-CPU depth state from allowing two
     * CPUs into shared process and VM state at the same time.
     */
    __asm__ __volatile__("mrs %0, daif" : "=r"(flags));
    __atomic_store_n(&cpu->kernel_execution_waiting, 1u,
                     __ATOMIC_RELEASE);
    for (;;) {
        uint64_t owner = __atomic_load_n(
            &g_kernel_execution_owner_hardware_plus_one, __ATOMIC_ACQUIRE);
        uint64_t expected = 0u;

        if (owner == owner_hardware_plus_one) {
            expected = owner;
            if (__atomic_compare_exchange_n(
                    &g_kernel_execution_owner_hardware_plus_one, &expected,
                    0u, 0, __ATOMIC_RELEASE, __ATOMIC_RELAXED)) {
                cpu->kernel_execution_depth = 0u;
                cpu->kernel_execution_irq_flags = 0u;
            }
            continue;
        }

        if (__atomic_compare_exchange_n(
                &g_kernel_execution_owner_hardware_plus_one, &expected,
                owner_hardware_plus_one, 0, __ATOMIC_ACQUIRE,
                __ATOMIC_RELAXED))
            break;
        __asm__ __volatile__(
            "msr daifclr, #2\n\tyield\n\tmsr daifset, #2"
            ::: "memory");
    }
    cpu->kernel_execution_irq_flags = flags;
    cpu->kernel_execution_depth = 1u;
    __atomic_store_n(&cpu->kernel_execution_waiting, 0u,
                     __ATOMIC_RELEASE);
    /*
     * Waiting for the architecture-wide runtime owner is an implementation
     * cost, not execution by the interrupted userspace task.  Charging that
     * interval to vruntime can move an interactive thread tens of seconds
     * ahead of its peers when several CPUs enter the kernel concurrently.
     * Move the local slice origin past the wait so the normal syscall or
     * timer accounting below sees only time the task actually controlled.
     */
    if (cpu->task_run_started_us) {
        uint64_t acquired_us = boottime_monotonic_us();

        if (acquired_us > wait_started_us) {
            uint64_t wait_us = acquired_us - wait_started_us;

            cpu->task_run_started_us =
                cpu->task_run_started_us > UINT64_MAX - wait_us ?
                acquired_us : cpu->task_run_started_us + wait_us;
            if (cpu->task_run_started_us > acquired_us)
                cpu->task_run_started_us = acquired_us;
        }
    }
    __asm__ __volatile__("msr daif, %0" :: "r"(flags) : "memory");
}

int edgeos_arm64_kernel_execution_try_enter(void) {
    arm64_scheduler_cpu_runtime_t *cpu = arm64_scheduler_cpu_local();
    uint64_t owner_hardware_plus_one =
        edgeos_arm64_smp_current_hardware_id() + 1u;
    uint64_t flags;
    uint64_t expected = 0u;

    if (cpu->kernel_execution_depth) {
        uint64_t owner = __atomic_load_n(
            &g_kernel_execution_owner_hardware_plus_one,
            __ATOMIC_ACQUIRE);

        if (owner == owner_hardware_plus_one) return 0;
        cpu->kernel_execution_depth = 0u;
        cpu->kernel_execution_irq_flags = 0u;
    }
    if (__atomic_load_n(&cpu->kernel_execution_waiting,
                        __ATOMIC_ACQUIRE))
        return 0;
    __asm__ __volatile__("mrs %0, daif" : "=r"(flags));
    if (!__atomic_compare_exchange_n(
            &g_kernel_execution_owner_hardware_plus_one, &expected,
            owner_hardware_plus_one, 0,
            __ATOMIC_ACQUIRE, __ATOMIC_RELAXED))
        return 0;
    cpu->kernel_execution_irq_flags = flags;
    cpu->kernel_execution_depth = 1u;
    return 1;
}

int edgeos_arm64_kernel_execution_waiting(void) {
    arm64_scheduler_cpu_runtime_t *cpu = arm64_scheduler_cpu_local();

    return __atomic_load_n(&cpu->kernel_execution_waiting,
                           __ATOMIC_ACQUIRE) != 0u;
}

static int kernel_execution_peer_waiting(uint32_t logical_cpu) {
    uint32_t cpu_count = edge_smp_present_count();

    if (cpu_count > EDGE_SMP_MAX_CPUS) cpu_count = EDGE_SMP_MAX_CPUS;
    for (uint32_t cpu = 0; cpu < cpu_count; ++cpu) {
        if (cpu == logical_cpu) continue;
        if (__atomic_load_n(
                &g_arm64_scheduler_cpus[cpu].kernel_execution_waiting,
                __ATOMIC_ACQUIRE))
            return 1;
    }
    return 0;
}

void edgeos_arm64_kernel_execution_exit(void) {
    arm64_scheduler_cpu_runtime_t *cpu = arm64_scheduler_cpu_local();
    uint32_t logical_cpu = edgeos_arm64_smp_current_cpu();
    uint64_t owner_hardware_plus_one =
        edgeos_arm64_smp_current_hardware_id() + 1u;
    uint64_t expected = owner_hardware_plus_one;
    uint64_t flags;

    if (!cpu->kernel_execution_depth) return;
    flags = cpu->kernel_execution_irq_flags;
    cpu->kernel_execution_depth = 0u;
    cpu->kernel_execution_irq_flags = 0u;
    cpu->kernel_execution_scheduler_handoffs = 0u;
    /* A stale local depth must never release another CPU's ownership. */
    (void)__atomic_compare_exchange_n(
        &g_kernel_execution_owner_hardware_plus_one, &expected, 0u, 0,
        __ATOMIC_RELEASE, __ATOMIC_RELAXED);
    if (expected == owner_hardware_plus_one &&
        kernel_execution_peer_waiting(logical_cpu)) {
        /*
         * Give an already waiting CPU a bounded handoff window. Without it,
         * syscall-heavy browser threads can repeatedly reacquire the owner
         * before a timer or compositor wake path observes the release. The
         * window is active only under contention and ends as soon as a peer
         * publishes ownership.
         */
        __asm__ __volatile__("dsb ishst\n\tsev" ::: "memory");
        for (uint32_t spin = 0; spin < 64u; ++spin) {
            if (__atomic_load_n(
                    &g_kernel_execution_owner_hardware_plus_one,
                    __ATOMIC_ACQUIRE) != 0u)
                break;
            __asm__ __volatile__("yield" ::: "memory");
        }
    }
    __asm__ __volatile__("msr daif, %0" :: "r"(flags) : "memory");
}

void edgeos_arm64_address_space_note_memory_oom(uint64_t ttbr0,
                                                uint32_t oom_cgroup_id) {
    kernel_task_t *active;

    if (!g_tasks) return;
    ttbr0 &= EDGEOS_ARM64_TTBR0_BASE_MASK;
    active = current_task();
    if (active && active->ttbr0 == ttbr0) {
        active->cgroup_memory_oom_id = oom_cgroup_id;
        return;
    }
    for (uint32_t slot = 0; slot < g_task_high_water; ++slot) {
        kernel_task_t *task = &g_tasks[slot];
        if (task->state == KERNEL_TASK_UNUSED || task->ttbr0 != ttbr0)
            continue;
        task->cgroup_memory_oom_id = oom_cgroup_id;
        return;
    }
}

uint64_t kernel_arch_scheduler_online_cpu_mask(void) {
    return edge_smp_online_mask64();
}

void edgeos_arm64_scheduler_secondary_prepare(uint32_t logical_id,
                                              uint64_t stack_top) {
    arm64_scheduler_cpu_runtime_t *cpu;

    if (logical_id >= EDGE_SMP_MAX_CPUS || !stack_top) return;
    cpu = &g_arm64_scheduler_cpus[logical_id];
    cpu->kernel_resume_sp = stack_top & ~0xfULL;
    cpu->task_run_started_us = 0u;
    cpu->kernel_execution_irq_flags = 0u;
    cpu->reschedule_target_plus_one = 0u;
    cpu->fuse_reschedule_target_plus_one = 0u;
    cpu->fuse_reply_target_plus_one = 0u;
    cpu->kernel_execution_depth = 0u;
    cpu->kernel_execution_waiting = 0u;
    cpu->kernel_execution_scheduler_handoffs = 0u;
    cpu->assigned_tasks = 0u;
}

int kernel_arch_scheduler_cpu_stats(
        uint32_t cpu, kernel_scheduler_cpu_stats_t *stats) {
    kernel_task_t *running = 0;
    uint64_t now_us;
    uint64_t live_us = 0u;
    uint64_t accounted;

    if (!stats || cpu >= EDGE_SMP_MAX_CPUS ||
        edge_smp_cpu_state(cpu) != EDGE_CPU_ONLINE)
        return -1;
    bytes_zero(stats, sizeof(*stats));
    now_us = boottime_monotonic_us();
    stats->user_time_us =
        __atomic_load_n(&g_scheduler_cpu_user_us[cpu], __ATOMIC_ACQUIRE);
    stats->system_time_us =
        __atomic_load_n(&g_scheduler_cpu_system_us[cpu], __ATOMIC_ACQUIRE);
    stats->runqueue_wait_us =
        __atomic_load_n(&g_scheduler_cpu_wait_us[cpu], __ATOMIC_ACQUIRE);
    stats->context_switches =
        __atomic_load_n(&g_scheduler_cpu_switches[cpu], __ATOMIC_ACQUIRE);
    stats->migrations =
        __atomic_load_n(&g_scheduler_cpu_migrations[cpu], __ATOMIC_ACQUIRE);

    for (uint32_t slot = 0; slot < g_task_high_water; ++slot) {
        if (!task_state_bitmap_test(g_task_active_bitmap, slot))
            continue;
        arm64_task_state_t state = task_state_shadow_at(slot);
        uint16_t owner = __atomic_load_n(
            &g_tasks[slot].scheduler_running_cpu_plus_one,
            __ATOMIC_ACQUIRE);

        if (state == KERNEL_TASK_RUNNING &&
            owner == (uint16_t)(cpu + 1u)) {
            running = &g_tasks[slot];
            if (stats->nr_running != UINT32_MAX) ++stats->nr_running;
        } else if (state == KERNEL_TASK_RUNNABLE &&
                   task_scheduler_cpu_allowed(&g_tasks[slot], cpu) &&
                   stats->nr_running != UINT32_MAX) {
            ++stats->nr_running;
        }
    }
    if (running) {
        if (g_arm64_scheduler_cpus[cpu].task_run_started_us &&
            now_us > g_arm64_scheduler_cpus[cpu].task_run_started_us)
            live_us = now_us -
                      g_arm64_scheduler_cpus[cpu].task_run_started_us;
        if (running && running->active_syscall_frame)
            stats->system_time_us =
                stats->system_time_us > UINT64_MAX - live_us ? UINT64_MAX :
                stats->system_time_us + live_us;
        else
            stats->user_time_us =
                stats->user_time_us > UINT64_MAX - live_us ? UINT64_MAX :
                stats->user_time_us + live_us;
    }
    accounted = stats->user_time_us > UINT64_MAX - stats->system_time_us ?
                UINT64_MAX : stats->user_time_us + stats->system_time_us;
    stats->idle_time_us = now_us > accounted ? now_us - accounted : 0u;
    return 0;
}

static int edge_process_runtime_fill_view(
    kernel_task_t *task, kernel_process_native_view_t *view) {
    if (!task || !view || task->state == KERNEL_TASK_UNUSED) return -1;
    bytes_zero(view, sizeof(*view));
    view->context_token = (uintptr_t)task;
    view->pid = task->pid;
    view->tgid = task_group_id(task);
    view->ppid = task->ppid;
    view->uid = task->uid;
    view->euid = task->euid;
    view->suid = task->suid;
    view->gid = task->gid;
    view->egid = task->egid;
    view->sgid = task->sgid;
    view->dumpable = task->dumpable;
    view->stopped = task->state == KERNEL_TASK_STOPPED;
    view->zombie = task->state == KERNEL_TASK_ZOMBIE;
    view->stop_reported = task->stop_reported;
    view->stop_signal = task->stop_signal;
    view->comm = task->comm;
    view->linux_thread = &task->linux_thread;
    view->namespaces = &task->namespaces;
    view->ptrace = &task->ptrace;
    view->signal_actions = task->signal_actions;
    view->signal_mask = &task->signal_mask;
    return 0;
}

int edge_process_runtime_current_view(
    kernel_process_native_view_t *view) {
    return edge_process_runtime_fill_view(current_task(), view);
}

int edge_process_runtime_view(
    int32_t pid, kernel_process_native_view_t *view) {
    int slot = task_find_pid(pid);
    return slot < 0 ? -1 :
        edge_process_runtime_fill_view(&g_tasks[slot], view);
}

int edge_system_runtime_memory_information_sample(
    kernel_memory_information_sample_t *sample) {
    if (!g_tasks) return -1;
    sample->total_ram_bytes = arch_vm_memory_total_bytes();
    sample->free_ram_bytes = arch_vm_memory_free_bytes();
    return 0;
}

int edge_process_runtime_group_page_allocate(linux_group_page_t *page) {
    void *storage;
    storage = arch_vm_alloc_page();
    if (!storage) return -1;
    page->values = (uint32_t *)storage;
    page->token = (uint64_t)(uintptr_t)storage;
    return 0;
}

int edge_process_runtime_group_page_retain(
    const linux_group_page_t *page) {
    if (!page || !page->values ||
        page->token != (uint64_t)(uintptr_t)page->values)
        return -1;
    return arch_vm_retain_page(page->values);
}

void edge_process_runtime_group_page_release(
    const linux_group_page_t *page) {
    if (!page || !page->values ||
        page->token != (uint64_t)(uintptr_t)page->values)
        return;
    arch_vm_free_page(page->values);
}

int kernel_arch_serial_console_device(kernel_console_device_t *device) {
    static const char name[] = "ttyAMA0";
    if (!device) return -1;
    bytes_zero(device, sizeof(*device));
    bytes_copy(device->name, name, sizeof(name));
    device->major = 204u;
    device->minor = 64u;
    return 0;
}

static int kernel_identity_view_from_task(
    const kernel_task_t *task, kernel_task_identity_view_t *view) {
    if (!task || !view || task->state == KERNEL_TASK_UNUSED) return -1;
    view->tid = task->pid;
    view->tgid = task->tgid;
    view->ppid = task->ppid;
    view->pgid = task->pgid;
    view->sid = task->sid;
    view->pid_namespace_id = edge_namespace_id(
        &task->namespaces, EDGE_NAMESPACE_PID);
    view->state = task->state == KERNEL_TASK_ZOMBIE ?
        KERNEL_PROC_TASK_ZOMBIE :
        task->state == KERNEL_TASK_STOPPED ? KERNEL_PROC_TASK_STOPPED :
        (task->state == KERNEL_TASK_RUNNING ||
         task->state == KERNEL_TASK_RUNNABLE) ?
            KERNEL_PROC_TASK_RUNNING : KERNEL_PROC_TASK_SLEEPING;
    view->uid = task->uid;
    view->euid = task->euid;
    view->suid = task->suid;
    view->fsuid = task->fsuid;
    view->gid = task->gid;
    view->egid = task->egid;
    view->sgid = task->sgid;
    view->fsgid = task->fsgid;
    view->dumpable = task->dumpable;
    view->permitted_capabilities = task->capabilities.permitted;
    view->effective_capabilities = task->capabilities.effective;
    return 0;
}

static int kernel_task_view_from_task(const kernel_task_t *task,
                                      kernel_proc_task_view_t *view) {
    kernel_task_identity_view_t identity;
    uint16_t processor_plus_one;
    if (kernel_identity_view_from_task(task, &identity) < 0 || !view)
        return -1;
    bytes_zero(view, sizeof(*view));
    kernel_proc_task_view_set_identity(view, &identity);
    if (task->has_controlling_tty) {
        bootstrap_fd_t tty_fd;
        kernel_tty_state_t *tty;
        bytes_zero(&tty_fd, sizeof(tty_fd));
        tty_fd.tty_identity = task->controlling_tty;
        tty = task_tty_state(task, &tty_fd);
        view->tty_pgrp = tty ? tty->session.foreground_pgid : 0;
    }
    view->nice_value = (int8_t)task->scheduler.nice;
    view->io_priority = task->io_priority;
    view->umask = (uint16_t)(task->umask & 0777u);
    view->parent_death_signal = task->parent_death_signal;
    view->no_new_privileges = task->no_new_privs;
    view->seccomp_mode = task->seccomp.length ?
        EDGE_LINUX_SECCOMP_MODE_FILTER : EDGE_LINUX_SECCOMP_MODE_DISABLED;
    view->thp_disabled = task->thp_disabled;
    view->execed_since_fork = task->execed_since_fork;
    view->child_subreaper = task->child_subreaper;
    view->oom_score_adj = task->oom_score_adj;
    view->oom_score_adj_min = task->oom_score_adj_min;
    view->timer_slack_ns = task->timer_slack_ns;
    view->default_timer_slack_ns = task->default_timer_slack_ns;
    linux_capabilities_copy(&view->capabilities, &task->capabilities);
    for (uint32_t resource = 0; resource < EDGE_LINUX_RLIMIT_COUNT;
         ++resource) {
        view->resource_limits[resource].current = task->rlimits[resource][0];
        view->resource_limits[resource].maximum = task->rlimits[resource][1];
    }
    view->scheduler = task->scheduler;
    view->scheduler_vruntime_us = task->scheduler_vruntime_us;
    view->scheduler_wait_us = task->scheduler_wait_us;
    view->scheduler_migrations = task->scheduler_migrations;
    processor_plus_one = __atomic_load_n(
        &task->scheduler_running_cpu_plus_one, __ATOMIC_ACQUIRE);
    if (!processor_plus_one)
        processor_plus_one = task->scheduler_last_cpu_plus_one;
    view->processor = processor_plus_one ?
        (uint32_t)processor_plus_one - 1u : 0u;
    if (task->scheduler_wait_start_us) {
        uint64_t now_us = boottime_monotonic_us();
        uint64_t pending_wait = now_us > task->scheduler_wait_start_us ?
            now_us - task->scheduler_wait_start_us : 0u;

        view->scheduler_wait_us =
            view->scheduler_wait_us > UINT64_MAX - pending_wait ?
            UINT64_MAX : view->scheduler_wait_us + pending_wait;
    }
    view->start_time_ticks = task->start_time_ticks;
    view->usage.user_time_us =
        task_ticks_to_microseconds(task->user_ticks);
    view->usage.sys_time_us =
        task_ticks_to_microseconds(task->system_ticks);
    view->usage.voluntary_ctxt_switches =
        task->scheduler_voluntary_switches;
    view->usage.involuntary_ctxt_switches =
        task->scheduler_involuntary_switches;
    view->usage.minor_faults = task->minor_faults;
    view->usage.major_faults = task->major_faults;
    view->children_usage.user_time_us =
        task_ticks_to_microseconds(task->children_user_ticks);
    view->children_usage.sys_time_us =
        task_ticks_to_microseconds(task->children_system_ticks);
    view->memory_context_id = task->ttbr0;
    view->files_context_id = task->files_id;
    view->fs_context_id = task->fs_id;
    view->sighand_context_id = task->sighand_id;
    /* EdgeOS has no independently allocated IO or SysV sem_undo context. */
    view->io_context_id = 0;
    view->sysvsem_context_id = 0;
    view->exec_file_handle = task->exec_file_handle;
    view->cgroup_id = task->cgroup_id;
    view->mount_namespace_id = task->mount_namespace;
    view->pid_namespace_id = edge_namespace_id(&task->namespaces,
                                               EDGE_NAMESPACE_PID);
    view->user_namespace_id = edge_namespace_id(&task->namespaces,
                                                EDGE_NAMESPACE_USER);
    view->syscall_nr = task->debug_last_syscall;
    for (uint32_t argument = 0; argument < 6u; ++argument)
        view->syscall_args[argument] =
            task->debug_last_syscall_args[argument];
    kernel_proc_task_view_set_names(view, task->comm, task->exec_path);
    return 0;
}

uint64_t arch_process_task_lock(void) {
    return spin_lock_irqsave(&g_task_lock);
}

void arch_process_task_unlock(uint64_t flags) {
    spin_unlock_irqrestore(&g_task_lock, flags);
}

uint32_t arch_process_task_capacity(void) {
    return g_tasks ? KERNEL_BOOTSTRAP_MAX_TASKS : 0;
}

kernel_process_task_handle_t arch_process_task_at_locked(uint32_t slot) {
    if (!g_tasks || slot >= KERNEL_BOOTSTRAP_MAX_TASKS) return 0;
    return (kernel_process_task_handle_t)(uintptr_t)&g_tasks[slot];
}

kernel_process_task_handle_t arch_process_task_find_locked(int32_t tid) {
    int slot;
    if (!g_tasks || tid <= 0) return 0;
    slot = task_find_pid(tid);
    if (slot < 0 || (uint32_t)slot >= g_task_high_water) return 0;
    return (kernel_process_task_handle_t)(uintptr_t)&g_tasks[slot];
}

kernel_process_task_handle_t arch_process_current_task_locked(void) {
    return (kernel_process_task_handle_t)(uintptr_t)current_task();
}

int arch_process_task_identity_locked(
    kernel_process_task_handle_t handle,
    kernel_task_identity_view_t *view) {
    kernel_task_t *task = (kernel_task_t *)(uintptr_t)handle;
    uintptr_t first;
    uintptr_t last;

    if (!g_tasks || !task || !view) return -1;
    first = (uintptr_t)&g_tasks[0];
    last = (uintptr_t)&g_tasks[KERNEL_BOOTSTRAP_MAX_TASKS];
    if ((uintptr_t)task < first || (uintptr_t)task >= last ||
        (((uintptr_t)task - first) % sizeof(*task)) != 0)
        return -1;
    return kernel_identity_view_from_task(task, view);
}

int arch_process_task_view_locked(kernel_process_task_handle_t handle,
                                  kernel_proc_task_view_t *view) {
    kernel_task_t *task = (kernel_task_t *)(uintptr_t)handle;
    uintptr_t first;
    uintptr_t last;

    if (!g_tasks || !task || !view) return -1;
    first = (uintptr_t)&g_tasks[0];
    last = (uintptr_t)&g_tasks[KERNEL_BOOTSTRAP_MAX_TASKS];
    if ((uintptr_t)task < first || (uintptr_t)task >= last ||
        (((uintptr_t)task - first) % sizeof(*task)) != 0)
        return -1;
    if (task->state == KERNEL_TASK_UNUSED) return 1;
    return kernel_task_view_from_task(task, view);
}

void arch_process_task_apply_locked(
    kernel_process_task_handle_t handle,
    const kernel_process_task_update_t *update) {
    kernel_task_t *task = (kernel_task_t *)(uintptr_t)handle;
    uint32_t slot;

    if (!g_tasks || !task || !update) return;
    slot = (uint32_t)(task - g_tasks);
    if (slot >= KERNEL_BOOTSTRAP_MAX_TASKS ||
        task->state == KERNEL_TASK_UNUSED)
        return;
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_SESSION) {
        task->pgid = update->pgid;
        task->sid = update->sid;
        if (update->detach_controlling_terminal)
            task->has_controlling_tty = 0;
    }
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_EXEC)
        task->execed_since_fork = update->execed_since_fork;
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_CGROUP) {
        task->cgroup_id = update->cgroup_id;
        edgeos_arm64_address_space_set_cgroup(task->ttbr0,
                                               update->cgroup_id);
    }
    if ((update->fields & KERNEL_PROCESS_TASK_UPDATE_RESOURCE_LIMIT) &&
        update->resource < EDGE_LINUX_RLIMIT_COUNT) {
        task->rlimits[update->resource][0] =
            update->resource_limit.current;
        task->rlimits[update->resource][1] =
            update->resource_limit.maximum;
    }
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_OOM) {
        task->oom_score_adj = update->oom_score_adj;
        task->oom_score_adj_min = update->oom_score_adj_min;
    }
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_IO_PRIORITY)
        task->io_priority = update->io_priority;
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_SCHEDULER) {
        edge_linux_scheduler_state_apply_updates(
            &task->scheduler, &update->scheduler,
            update->scheduler_update_mask);
        if (update->scheduler_update_mask & EDGE_SCHEDULER_UPDATE_POLICY) {
            edge_linux_scheduler_entity_init(
                &task->scheduler_entity, &task->scheduler,
                boottime_monotonic_us());
            g_reschedule_target_plus_one = (uint16_t)(slot + 1u);
        }
        if ((update->scheduler_update_mask &
             EDGE_SCHEDULER_UPDATE_AFFINITY) &&
            task->state == KERNEL_TASK_RUNNABLE)
            task_scheduler_remote_wake(task);
    }
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_CREDENTIALS) {
        if (update->clear_parent_death_signal)
            task->parent_death_signal = 0;
        task->uid = update->credentials.uid;
        task->euid = update->credentials.euid;
        task->suid = update->credentials.suid;
        task->fsuid = update->credentials.fsuid;
        task->gid = update->credentials.gid;
        task->egid = update->credentials.egid;
        task->sgid = update->credentials.sgid;
        task->fsgid = update->credentials.fsgid;
        linux_capabilities_copy(
            &task->capabilities, &update->credentials.capabilities);
    }
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_GROUPS) {
        if (!update->groups) {
            int result = linux_group_list_retain(
                update->previous_groups,
                &task->supplementary_groups);
            if (update->result) *update->result = result;
        } else if (update->previous_groups) {
            *update->previous_groups = task->supplementary_groups;
            task->supplementary_groups = *update->groups;
            linux_group_list_init(update->groups);
            if (update->result) *update->result = 0;
        }
    }
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_UMASK)
        task->umask = update->umask;
    if (update->fields & KERNEL_PROCESS_TASK_UPDATE_PRCTL) {
        if (update->prctl_update_mask &
            EDGE_LINUX_PRCTL_UPDATE_PARENT_DEATH_SIGNAL) {
            task->parent_death_signal =
                update->prctl.parent_death_signal;
        }
        if (update->prctl_update_mask &
            EDGE_LINUX_PRCTL_UPDATE_DUMPABLE)
            task->dumpable = update->prctl.dumpable;
        if (update->prctl_update_mask &
            EDGE_LINUX_PRCTL_UPDATE_NO_NEW_PRIVILEGES) {
            task->no_new_privs =
                update->prctl.no_new_privileges ? 1u : 0u;
        }
        if (update->prctl_update_mask &
            EDGE_LINUX_PRCTL_UPDATE_TIMER_SLACK)
            task->timer_slack_ns = update->prctl.timer_slack_ns;
        if (update->prctl_update_mask &
            EDGE_LINUX_PRCTL_UPDATE_THP_DISABLED)
            task->thp_disabled = update->prctl.thp_disabled;
        if (update->prctl_update_mask &
            EDGE_LINUX_PRCTL_UPDATE_CHILD_SUBREAPER) {
            task->child_subreaper =
                update->prctl.child_subreaper ? 1u : 0u;
        }
        if (update->prctl_update_mask & EDGE_LINUX_PRCTL_UPDATE_NAME) {
            bytes_zero(task->comm, sizeof(task->comm));
            for (uint32_t index = 0;
                 index + 1u < sizeof(task->comm); ++index) {
                task->comm[index] = update->prctl.name[index];
                if (!update->prctl.name[index]) break;
            }
        }
    }
}

edge_seccomp_state_t *arch_process_task_seccomp_locked(
    kernel_process_task_handle_t handle) {
    kernel_task_t *task = (kernel_task_t *)(uintptr_t)handle;
    if (!task || task->state == KERNEL_TASK_UNUSED) return 0;
    return &task->seccomp;
}

void arch_process_task_seccomp_replace_locked(
    kernel_process_task_handle_t handle,
    const edge_seccomp_state_t *installed, int set_no_new_privileges) {
    kernel_task_t *task = (kernel_task_t *)(uintptr_t)handle;
    if (!task || task->state == KERNEL_TASK_UNUSED || !installed) return;
    edge_seccomp_state_release(&task->seccomp);
    task->seccomp = *installed;
    if (set_no_new_privileges) task->no_new_privs = 1;
}

uint32_t *arch_process_task_membarrier_locked(
    kernel_process_task_handle_t handle) {
    kernel_task_t *task = (kernel_task_t *)(uintptr_t)handle;
    if (!task || task->state == KERNEL_TASK_UNUSED) return 0;
    return &task->membarrier_registrations;
}

int edge_process_runtime_fs_snapshot(
    int32_t pid, char *cwd, uint32_t cwd_capacity,
    char *root, uint32_t root_capacity) {
    uint64_t flags;
    int status = -EDGE_LINUX_ESRCH;

    if (!g_tasks || pid <= 0 ||
        ((!cwd || !cwd_capacity) && (!root || !root_capacity)))
        return -EDGE_LINUX_EINVAL;
    flags = spin_lock_irqsave(&g_task_lock);
    {
        int slot = task_find_pid(pid);
        kernel_task_t *task =
            slot >= 0 ? &g_tasks[(uint32_t)slot] : 0;
        if (task && task->state != KERNEL_TASK_UNUSED &&
            task->state != KERNEL_TASK_ZOMBIE) {
            status = 0;
            if (cwd)
                status = kernel_fs_context_copy_path(
                    cwd, cwd_capacity,
                    task->cwd[0] ? task->cwd : "/");
            if (status == 0 && root)
                status = kernel_fs_context_copy_path(
                    root, root_capacity,
                    task->root[0] ? task->root : "/");
        }
    }
    spin_unlock_irqrestore(&g_task_lock, flags);
    return status;
}

int arch_proc_namespace_inode(int32_t pid, uint32_t kind,
                              uint64_t *inode_out) {
    kernel_task_t *task = 0;
    uint64_t inode;
    if (!inode_out || kind >= EDGE_NAMESPACE_KIND_COUNT || pid <= 0)
        return -1;
    for (uint32_t slot = 0; slot < g_task_high_water; ++slot) {
        if (g_tasks[slot].state != KERNEL_TASK_UNUSED &&
            g_tasks[slot].pid == pid) {
            task = &g_tasks[slot];
            break;
        }
    }
    if (!task) return -1;
    inode = edge_namespace_inode(&task->namespaces,
        (edge_namespace_kind_t)kind);
    if (!inode) return -1;
    *inode_out = inode;
    return 0;
}

int arch_proc_task_cmdline(int32_t pid, char *buffer, uint32_t capacity) {
    kernel_task_t *task = 0;
    uint64_t length;
    if (!g_tasks || !buffer || pid <= 0) return -1;
    for (uint32_t index = 0; index < g_task_high_water; ++index) {
        if (g_tasks[index].state != KERNEL_TASK_UNUSED &&
            g_tasks[index].pid == pid) {
            task = &g_tasks[index];
            break;
        }
    }
    if (!task) return -1;
    if (!task->arg_start || task->arg_end < task->arg_start) return 0;
    length = task->arg_end - task->arg_start;
    if (length > capacity || length > INT32_MAX) return -1;
    if (length && arch_copy_from_user(task->ttbr0, buffer, task->arg_start,
                                     length) < 0)
        return -1;
    return (int)length;
}

int arch_proc_task_environ(int32_t pid, char *buffer, uint32_t capacity) {
    kernel_task_t *task = 0;
    uint64_t length;
    if (!g_tasks || !buffer || pid <= 0) return -1;
    for (uint32_t index = 0; index < g_task_high_water; ++index) {
        if (g_tasks[index].state != KERNEL_TASK_UNUSED &&
            g_tasks[index].pid == pid) {
            task = &g_tasks[index];
            break;
        }
    }
    if (!task) return -1;
    if (!task->env_start || task->env_end < task->env_start) return 0;
    length = task->env_end - task->env_start;
    if (length > capacity || length > INT32_MAX) return -1;
    if (length && arch_copy_from_user(task->ttbr0, buffer, task->env_start,
                                     length) < 0)
        return -1;
    return (int)length;
}

__attribute__((noreturn)) void kernel_fault_current(uint32_t signal) {
    task_finish(current_task(), 0, signal, 1);
}

static void task_finish_memory_oom_if_pending(kernel_task_t *task) {
    uint32_t oom_cgroup_id;

    if (!task || !task->cgroup_memory_oom_id) return;
    oom_cgroup_id = task->cgroup_memory_oom_id;
    task->cgroup_memory_oom_id = 0;
    (void)cgroupfs_memory_oom_group_kill(
        oom_cgroup_id, task_group_id(task));
    cgroupfs_memory_note_oom_kill(task->cgroup_id);
    task_finish(task, 0, 9u, 1);
}

static void task_note_page_fault(kernel_task_t *task, int major) {
    uint64_t *counter;

    if (!task) return;
    counter = major ? &task->major_faults : &task->minor_faults;
    if (*counter != UINT64_MAX) ++*counter;
    cgroupfs_memory_note_fault(task->cgroup_id, major);
    edge_mm_statistics_note_fault(major);
}

int arch_procfd_at(int32_t pid, uint32_t ordinal, uint32_t *fd_out) {
    int slot = task_find_pid(pid);
    kernel_task_t *task;
    if (slot < 0 || !fd_out) return -1;
    task = &g_tasks[slot];
    for (uint32_t fd = 0; fd < KERNEL_BOOTSTRAP_FD_MAX; ++fd) {
        if (!fd_slot_is_open(task, fd)) continue;
        if (ordinal == 0u) {
            *fd_out = fd;
            return 0;
        }
        --ordinal;
    }
    return -1;
}

int kernel_handle_page_fault(arch_user_frame_t *frame) {
    kernel_task_t *task = current_task();
    uint32_t ec;
    uint32_t fault_status;
    uint32_t access;
    uint32_t is_write;
    uint64_t page;
    uint64_t mapping;

    if (!task || !frame) return 0;
    ec = (uint32_t)(frame->esr >> 26);
    fault_status = (uint32_t)(frame->esr & 0x3fu);
    if (ec != 0x20u && ec != 0x24u && ec != 0x25u) return 0;
    page = frame->far & ~(PAGE_SIZE - 1u);
    /*
     * AArch64 reports EL0 cache-maintenance translation faults as data
     * aborts with ISS.CM set.  ISS.WnR is not a store classification for
     * those operations, so treating it as one rejects demand paging of an
     * executable mapping before dc cvau can maintain a freshly generated
     * instruction stream.
     */
    is_write = ec != 0x20u && !(frame->esr & (1u << 8)) &&
               (frame->esr & (1u << 6));
    access = ec == 0x20u ? KERNEL_MM_PROT_EXEC :
             (is_write ? KERNEL_MM_PROT_WRITE : KERNEL_MM_PROT_READ);
    if (fault_status >= 4u && fault_status <= 7u &&
        user_page_resident(task->ttbr0, page) &&
        arch_vm_retry_user_page(task->ttbr0, page) > 0) {
        task_note_page_fault(task, 0);
        return 1;
    }
    if (fault_status >= 13u && fault_status <= 15u &&
        edgeos_arm64_address_space_retry_user_access(
            task->ttbr0, page, access) > 0) {
        task_note_page_fault(task, 0);
        return 1;
    }
    if ((fault_status >= 4u && fault_status <= 7u) ||
        (fault_status >= 13u && fault_status <= 15u)) {
        int resolved = tmpfs_mapping_resolve_page(
            task->ttbr0, page, access);
        if (resolved != 0) {
            if (resolved < 0) task_finish_memory_oom_if_pending(task);
            else task_note_page_fault(task, 0);
            return resolved > 0;
        }
        resolved = file_mapping_resolve_page(task->ttbr0, page, access);
        if (resolved != 0) {
            if (resolved < 0) task_finish_memory_oom_if_pending(task);
            else task_note_page_fault(task, resolved > 1);
            return resolved > 0;
        }
        resolved = anon_mapping_resolve_page(task->ttbr0, page, access);
        if (resolved != 0) {
            if (resolved < 0) task_finish_memory_oom_if_pending(task);
            else task_note_page_fault(task, resolved > 1);
            return resolved > 0;
        }
    }
    if (is_write && fault_status >= 13u &&
        fault_status <= 15u) {
        uint64_t physical;
        int notified = arch_vm_handle_write_notify_fault(task->ttbr0, page,
                                                          &physical);
        if (notified > 0) {
            uint64_t fb_base;
            uint64_t fb_offset;
            uint64_t fb_size = (uint64_t)fb.pitch * fb.height;
            uint32_t fb_pages;
            (void)file_mapping_mark_dirty(task->ttbr0, page, physical);
            (void)edge_drm_note_mmap_dirty_physical(physical, PAGE_SIZE);
            if (fb_get_2m_phys_window(&fb_base, &fb_pages, &fb_offset)) {
                uint64_t visible_start = fb_base + fb_offset;
                uint64_t page_start = physical > visible_start ?
                                      physical : visible_start;
                uint64_t page_end = physical + PAGE_SIZE;
                uint64_t visible_end = visible_start + fb_size;
                (void)fb_pages;
                if (page_end > visible_end) page_end = visible_end;
                if (page_end > page_start)
                    fb_note_user_mmap_dirty(page_start - visible_start,
                                            page_end - page_start);
            }
            task_note_page_fault(task, 0);
            return 1;
        }
        if (notified < 0) {
            task_finish_memory_oom_if_pending(task);
            return 0;
        }
        int cow = arch_vm_handle_cow_fault(task->ttbr0, page);
        if (cow != 0) {
            vfs_inode_lifetime_finish_alias_release();
            if (cow < 0) task_finish_memory_oom_if_pending(task);
            else task_note_page_fault(task, 0);
            return cow > 0;
        }
    }
    if (ec != 0x24u) return 0;
    if (fault_status < 4u || fault_status > 7u) return 0;
    if (!task->stack_low || page >= task->stack_low ||
        page < USER_STACK_TOP - USER_STACK_LIMIT_BYTES ||
        frame->far + USER_STACK_INITIAL_BYTES < frame->sp_el0) return 0;
    mapping = task->stack_low;
    while (mapping > page) {
        uint8_t *storage;
        mapping -= PAGE_SIZE;
        storage = (uint8_t *)arch_vm_alloc_page();
        if (!storage || arch_vm_map_user_page(task->ttbr0,
                mapping, (uint64_t)(uintptr_t)storage,
                ARCH_VM_PROT_READ | ARCH_VM_PROT_WRITE) < 0) {
            task_finish_memory_oom_if_pending(task);
            return 0;
        }
        task->stack_low = mapping;
    }
    task_note_page_fault(task, 0);
    return 1;
}

static uint32_t current_task_slot(void) {
    kernel_task_t *task = current_task();
    if (!task) return KERNEL_BOOTSTRAP_MAX_TASKS;
    return (uint32_t)(task - &g_tasks[0]);
}

static void current_task_set(uint32_t slot) {
    arch_cpu_set_current_task((uint64_t)(uintptr_t)&g_tasks[slot]);
}

static void task_scheduler_load_decrement(uint32_t cpu) {
    volatile uint32_t *load;
    uint32_t observed;

    if (cpu >= EDGE_SMP_MAX_CPUS) return;
    load = &g_arm64_scheduler_cpus[cpu].assigned_tasks;
    observed = __atomic_load_n(load, __ATOMIC_ACQUIRE);
    while (observed && !__atomic_compare_exchange_n(
               load, &observed, observed - 1u, 0,
               __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
    }
}

static void task_scheduler_account_cpu(kernel_task_t *task,
                                       uint16_t cpu_plus_one) {
    uint16_t previous;

    if (!task) return;
    if (cpu_plus_one > EDGE_SMP_MAX_CPUS) cpu_plus_one = 0u;
    previous = __atomic_exchange_n(
        &task->scheduler_accounted_cpu_plus_one,
        cpu_plus_one, __ATOMIC_ACQ_REL);
    if (previous == cpu_plus_one) return;
    if (previous)
        task_scheduler_load_decrement((uint32_t)previous - 1u);
    if (cpu_plus_one)
        __atomic_fetch_add(
            &g_arm64_scheduler_cpus[cpu_plus_one - 1u].assigned_tasks,
            1u, __ATOMIC_ACQ_REL);
}

static void task_scheduler_remote_wake(kernel_task_t *task) {
    uint64_t targets;
    uint32_t loads[EDGE_SMP_MAX_CPUS];
    uint32_t current;
    uint32_t cpu_count;
    uint32_t target;
    uint32_t slot;

    if (!task) return;
    targets = task->scheduler.affinity_mask &
        cgroupfs_cpuset_cpu_mask64(task->cgroup_id) &
        edge_smp_online_mask64();
    current = edgeos_arm64_smp_current_cpu();
    cpu_count = edge_smp_present_count();
    if (cpu_count > EDGE_SMP_MAX_CPUS) cpu_count = EDGE_SMP_MAX_CPUS;
    for (uint32_t cpu = 0; cpu < cpu_count; ++cpu)
        loads[cpu] = __atomic_load_n(
            &g_arm64_scheduler_cpus[cpu].assigned_tasks,
            __ATOMIC_ACQUIRE);
    for (uint32_t cpu = cpu_count; cpu < EDGE_SMP_MAX_CPUS; ++cpu)
        loads[cpu] = UINT32_MAX;
    /*
     * This runs while the architecture execution lock serializes scheduler
     * state. Per-CPU counters keep wake placement proportional without
     * scanning the complete task table for every browser futex wakeup. The
     * bounded CPU-array read prevents the execution-lock convoy while still
     * allowing browser workers to use every online processor.
     */
    target = edge_linux_scheduler_least_loaded_wake_cpu(
        targets, task->scheduler_last_cpu_plus_one, current,
        loads, cpu_count);
    if (target >= EDGE_SMP_MAX_CPUS) return;
    slot = (uint32_t)(task - &g_tasks[0]);
    __atomic_store_n(&task->scheduler_placement_cpu_plus_one,
                     (uint16_t)(target + 1u), __ATOMIC_RELEASE);
    task_scheduler_account_cpu(task, (uint16_t)(target + 1u));
    __atomic_store_n(
        &g_arm64_scheduler_cpus[target].reschedule_target_plus_one,
        (uint16_t)(slot + 1u), __ATOMIC_RELEASE);
    if (target != current && edge_smp_reschedule(target) < 0) {
        uint16_t expected = (uint16_t)(slot + 1u);

        (void)__atomic_compare_exchange_n(
            &g_arm64_scheduler_cpus[target].reschedule_target_plus_one,
            &expected, 0u, 0, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE);
        __atomic_store_n(&task->scheduler_placement_cpu_plus_one, 0u,
                         __ATOMIC_RELEASE);
        task_scheduler_account_cpu(task, 0u);
    }
}

static int task_state_bitmap_test(const uint64_t *bitmap, uint32_t slot) {
    uint64_t word;

    if (!bitmap || slot >= KERNEL_BOOTSTRAP_MAX_TASKS) return 0;
    word = __atomic_load_n(&bitmap[slot >> 6], __ATOMIC_ACQUIRE);
    return (word & (UINT64_C(1) << (slot & 63u))) != 0u;
}

static void task_state_bitmap_update(uint32_t slot,
                                     arm64_task_state_t state) {
    uint64_t mask;
    uint32_t word;
    int active;

    if (slot >= KERNEL_BOOTSTRAP_MAX_TASKS) return;
    word = slot >> 6;
    mask = UINT64_C(1) << (slot & 63u);
    active = state == KERNEL_TASK_RUNNING ||
             state == KERNEL_TASK_RUNNABLE;
    if (active)
        __atomic_fetch_or(&g_task_active_bitmap[word], mask,
                          __ATOMIC_RELEASE);
    else
        __atomic_fetch_and(&g_task_active_bitmap[word], ~mask,
                           __ATOMIC_RELEASE);
    if (state == KERNEL_TASK_RUNNABLE)
        __atomic_fetch_or(&g_task_runnable_bitmap[word], mask,
                          __ATOMIC_RELEASE);
    else
        __atomic_fetch_and(&g_task_runnable_bitmap[word], ~mask,
                           __ATOMIC_RELEASE);
}

static void task_scheduler_place_runnable(kernel_task_t *task,
                                          int woke_from_wait);

static void task_state_set(kernel_task_t *task,
                           arm64_task_state_t state) {
    uintptr_t base;
    uintptr_t value;
    uintptr_t end;
    uint32_t slot;
    arm64_task_state_t previous;
    uint64_t now_us;

    if (!task) return;
    if ((state == KERNEL_TASK_RUNNABLE ||
         state == KERNEL_TASK_RUNNING) &&
        __atomic_load_n(&task->ttbr0, __ATOMIC_ACQUIRE) == 0u) {
        /*
         * Address-space release can synchronously notify a wait source.  An
         * exiting task is detached before those callbacks run and must never
         * be republished after its translation root has gone away.
         */
        return;
    }
    previous = task->state;
    if (previous != state &&
        (state == KERNEL_TASK_RUNNABLE ||
         (previous == KERNEL_TASK_RUNNABLE &&
          state == KERNEL_TASK_RUNNING))) {
        now_us = boottime_monotonic_us();
        if (state == KERNEL_TASK_RUNNABLE) {
            if (!task->scheduler_wait_start_us)
                task->scheduler_wait_start_us = now_us;
        } else if (task->scheduler_wait_start_us) {
            uint64_t wait = now_us > task->scheduler_wait_start_us ?
                now_us - task->scheduler_wait_start_us : 0u;

            task->scheduler_wait_us =
                task->scheduler_wait_us > UINT64_MAX - wait ? UINT64_MAX :
                task->scheduler_wait_us + wait;
            task_scheduler_counter_add(
                &g_scheduler_cpu_wait_us[edgeos_arm64_smp_current_cpu()],
                wait);
            task->scheduler_wait_start_us = 0u;
        }
    }
    if (!g_tasks) {
        task->state = state;
        return;
    }
    base = (uintptr_t)&g_tasks[0];
    value = (uintptr_t)task;
    end = (uintptr_t)&g_tasks[KERNEL_BOOTSTRAP_MAX_TASKS];
    if (value < base || value >= end) {
        task->state = state;
        return;
    }
    slot = (uint32_t)(task - &g_tasks[0]);
    if (state == KERNEL_TASK_RUNNABLE &&
        previous != KERNEL_TASK_RUNNABLE &&
        previous != KERNEL_TASK_RUNNING)
        task_scheduler_place_runnable(task, 1);
    task_state_bitmap_update(slot, state);
    if (state == KERNEL_TASK_RUNNABLE) {
        task_scheduler_account_cpu(task, 0u);
        __atomic_store_n(&task->scheduler_placement_cpu_plus_one, 0u,
                         __ATOMIC_RELEASE);
        task->state = state;
        __atomic_store_n(&task->scheduler_running_cpu_plus_one, 0u,
                         __ATOMIC_RELEASE);
        __atomic_store_n(
            &g_task_state_shadow[slot], (uint8_t)state,
            __ATOMIC_RELEASE);
        if (previous != KERNEL_TASK_RUNNABLE &&
            previous != KERNEL_TASK_RUNNING)
            task_scheduler_remote_wake(task);
        else if (previous == KERNEL_TASK_RUNNING &&
                 !task_scheduler_cpu_allowed(
                     task, edgeos_arm64_smp_current_cpu()))
            task_scheduler_remote_wake(task);
        else {
            uint32_t cpu = edgeos_arm64_smp_current_cpu();

            task_scheduler_account_cpu(
                task, cpu < EDGE_SMP_MAX_CPUS ?
                (uint16_t)(cpu + 1u) :
                task->scheduler_last_cpu_plus_one);
        }
        return;
    }
    if (state != KERNEL_TASK_RUNNING)
        __atomic_store_n(&task->scheduler_running_cpu_plus_one, 0u,
                         __ATOMIC_RELEASE);
    if (state != KERNEL_TASK_RUNNABLE)
        __atomic_store_n(&task->scheduler_placement_cpu_plus_one, 0u,
                         __ATOMIC_RELEASE);
    if (state != KERNEL_TASK_RUNNING && state != KERNEL_TASK_RUNNABLE)
        task_scheduler_account_cpu(task, 0u);
    __atomic_store_n(
        &g_task_state_shadow[slot], (uint8_t)state,
        __ATOMIC_RELEASE);
    __asm__ volatile("" ::: "memory");
    task->state = state;
    if (state == KERNEL_TASK_RUNNING) {
        uint32_t cpu = edgeos_arm64_smp_current_cpu();

        task->scheduler_last_cpu_plus_one = (uint16_t)(cpu + 1u);
        task_scheduler_account_cpu(task, (uint16_t)(cpu + 1u));
        __atomic_store_n(&task->scheduler_running_cpu_plus_one,
                         (uint16_t)(cpu + 1u), __ATOMIC_RELEASE);
    }
}

static arm64_task_state_t task_state_shadow_at(uint32_t slot) {
    if (slot >= KERNEL_BOOTSTRAP_MAX_TASKS)
        return KERNEL_TASK_UNUSED;
    return (arm64_task_state_t)__atomic_load_n(
        &g_task_state_shadow[slot], __ATOMIC_ACQUIRE);
}

static int task_scheduler_cpu_allowed(
        const kernel_task_t *task, uint32_t cpu) {
    uint64_t bit;
    uint64_t cpuset;

    if (!task || cpu >= 64u) return 0;
    bit = 1ULL << cpu;
    if (!(task->scheduler.affinity_mask & bit)) return 0;
    cpuset = cgroupfs_cpuset_cpu_mask64(task->cgroup_id);
    return (cpuset & bit) != 0u;
}

static int task_scheduler_placement_allows(
        const kernel_task_t *task, uint32_t cpu, uint64_t now_us) {
    uint16_t placement;

    if (!task) return 0;
    placement = __atomic_load_n(
        &task->scheduler_placement_cpu_plus_one, __ATOMIC_ACQUIRE);
    if (!placement || placement == (uint16_t)(cpu + 1u)) return 1;
    /*
     * A remote wake notification is only a placement hint.  If its target is
     * delayed or already idle, keeping the task pinned to that notification
     * forever can leave input and terminal work runnable while another CPU
     * scans an empty local queue.  Preserve short-term cache affinity, then
     * allow any permitted CPU to claim the task after the shared migration
     * cost just as a work-conserving Linux run queue would.
     */
    return edge_linux_scheduler_fair_migration_ready(
        placement, cpu, task->scheduler_wait_start_us, now_us);
}

static int task_try_claim_runnable(uint32_t slot) {
    kernel_task_t *task;
    uint8_t expected = (uint8_t)KERNEL_TASK_RUNNABLE;
    uint32_t cpu;
    uint16_t previous_cpu_plus_one;

    if (slot >= g_task_high_water) return 0;
    task = &g_tasks[slot];
    if (__atomic_load_n(&task->ttbr0, __ATOMIC_ACQUIRE) == 0u)
        return 0;
    cpu = edgeos_arm64_smp_current_cpu();
    if (!task_scheduler_cpu_allowed(task, cpu)) return 0;
    if (!task_scheduler_placement_allows(
            task, cpu, boottime_monotonic_us()))
        return 0;
    if (!__atomic_compare_exchange_n(
            &g_task_state_shadow[slot], &expected,
            (uint8_t)KERNEL_TASK_RUNNING, 0,
            __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE))
        return 0;
    if (__atomic_load_n(&task->ttbr0, __ATOMIC_ACQUIRE) == 0u) {
        task_state_set(task, KERNEL_TASK_EMBRYO);
        return 0;
    }
    __atomic_store_n(&task->scheduler_placement_cpu_plus_one, 0u,
                     __ATOMIC_RELEASE);
    previous_cpu_plus_one = task->scheduler_last_cpu_plus_one;
    task_state_set(task, KERNEL_TASK_RUNNING);
    if (previous_cpu_plus_one &&
        previous_cpu_plus_one != (uint16_t)(cpu + 1u)) {
        if (task->scheduler_migrations != UINT64_MAX)
            task->scheduler_migrations++;
        task_scheduler_counter_add(&g_scheduler_cpu_migrations[cpu], 1u);
    }
    return 1;
}

static int fd_retain(const bootstrap_fd_t *fd);
static int fd_retain_backing_object(const bootstrap_fd_t *fd);
static void fd_drop_backing_object(bootstrap_fd_t *fd);
static void fd_drop_reference(bootstrap_fd_t *fd);
static int fd_release(kernel_task_t *task, uint32_t number);
static int fd_slot_is_open(const kernel_task_t *owner, uint32_t fd);
static int fd_publish_thread_group(kernel_task_t *owner, uint32_t fd);
static void fd_cancel_constructed_descriptor(kernel_task_t *owner,
                                             uint32_t fd);

static void task_copy_words(void *destination, const void *source, uint64_t bytes) {
    uint64_t *d = (uint64_t *)destination;
    const uint64_t *s = (const uint64_t *)source;
    uint64_t i;
    for (i = 0; i < bytes / sizeof(*d); ++i) d[i] = s[i];
}

static arm64_fd_table_t *fd_table_from_entries(bootstrap_fd_t *entries) {
    if (!entries) return 0;
    return (arm64_fd_table_t *)((uint8_t *)entries -
        __builtin_offsetof(arm64_fd_table_t, entries));
}

static arm64_fd_table_t *fd_table_reserve_take(void) {
    arm64_fd_table_t *table;
    uint64_t flags = spin_lock_irqsave(&g_fd_table_reserve_lock);

    table = g_fd_table_reserve;
    if (table) {
        g_fd_table_reserve = table->free_next;
        table->free_next = 0;
        if (g_fd_table_reserve_count) --g_fd_table_reserve_count;
    }
    spin_unlock_irqrestore(&g_fd_table_reserve_lock, flags);
    return table;
}

static void fd_table_storage_release(arm64_fd_table_t *table) {
    uint32_t pages;
    uint64_t flags;

    if (!table) return;
    pages = table->page_count;
    flags = spin_lock_irqsave(&g_fd_table_reserve_lock);
    if (g_fd_table_reserve_count < ARM64_FD_TABLE_RESERVE_MAX) {
        table->free_next = g_fd_table_reserve;
        g_fd_table_reserve = table;
        ++g_fd_table_reserve_count;
        spin_unlock_irqrestore(&g_fd_table_reserve_lock, flags);
        return;
    }
    spin_unlock_irqrestore(&g_fd_table_reserve_lock, flags);
    for (uint32_t page = 0; page < pages; ++page)
        arch_vm_free_page(
            (uint8_t *)table + (uint64_t)page * PAGE_SIZE);
}

static void fd_table_reserve_populate(void) {
    const uint32_t pages = (uint32_t)(
        (sizeof(arm64_fd_table_t) + PAGE_SIZE - 1u) / PAGE_SIZE);

    while (g_fd_table_reserve_count < ARM64_FD_TABLE_RESERVE_MAX) {
        arm64_fd_table_t *table =
            (arm64_fd_table_t *)arch_vm_alloc_pages(pages);

        if (!table) break;
        table->page_count = pages;
        fd_table_storage_release(table);
    }
}

static bootstrap_fd_t *fd_table_allocate(const bootstrap_fd_t *source) {
    const uint64_t bytes = sizeof(arm64_fd_table_t);
    const uint32_t pages = (uint32_t)((bytes + PAGE_SIZE - 1u) / PAGE_SIZE);
    arm64_fd_table_t *table = fd_table_reserve_take();
    arm64_fd_table_t *source_table = fd_table_from_entries(
        (bootstrap_fd_t *)(uintptr_t)source);
    uint64_t source_flags = 0;
    int clone_result = 0;

    if (!table)
        table = (arm64_fd_table_t *)arch_vm_alloc_pages(pages);
    if (!table) return 0;
    for (uint64_t offset = 0; offset < (uint64_t)pages * PAGE_SIZE;
         offset += sizeof(uint64_t))
        *(uint64_t *)((uint8_t *)table + offset) = 0;
    table->references = 1u;
    table->task_references = 1u;
    table->page_count = pages;
    if (kernel_fd_table_runtime_initialize(
            &table->runtime, table->slot_states,
            KERNEL_BOOTSTRAP_FD_MAX) < 0)
        clone_result = -LINUX_EINVAL;
    if (!clone_result && source && !source_table)
        clone_result = -LINUX_EINVAL;
    if (!clone_result && source) {
        source_flags = kernel_fd_table_lock(&source_table->runtime);
        for (uint32_t descriptor = 0;
             descriptor < KERNEL_BOOTSTRAP_FD_MAX; ++descriptor) {
            if (!kernel_fd_table_is_open_locked(
                    &source_table->runtime, descriptor))
                continue;
            if (!source[descriptor].used) {
                clone_result = -LINUX_EBADF;
                break;
            }
            table->entries[descriptor] = source[descriptor];
            clone_result = fd_retain(&table->entries[descriptor]);
            if (clone_result < 0) {
                bytes_zero(&table->entries[descriptor],
                           sizeof(table->entries[descriptor]));
                break;
            }
            /*
             * The private table is not reachable yet. Copy only stable OPEN
             * slots and never inherit another task's transient reservation or
             * close transaction.
             */
            table->slot_states[descriptor] = KERNEL_FD_SLOT_OPEN;
        }
        if (!clone_result) {
            uint64_t destination_flags =
                kernel_fd_table_lock(&table->runtime);
            clone_result =
                kernel_fd_table_inherit_allocated_limit_locked(
                    &table->runtime, &source_table->runtime);
            kernel_fd_table_unlock(
                &table->runtime, destination_flags);
        }
        kernel_fd_table_unlock(&source_table->runtime, source_flags);
    }
    if (clone_result < 0) {
        for (uint32_t descriptor = 0;
             descriptor < KERNEL_BOOTSTRAP_FD_MAX; ++descriptor) {
            if (table->slot_states[descriptor] != KERNEL_FD_SLOT_OPEN)
                continue;
            fd_drop_reference(&table->entries[descriptor]);
            table->slot_states[descriptor] = KERNEL_FD_SLOT_FREE;
        }
        fd_table_storage_release(table);
        return 0;
    }
    return table->entries;
}

static void fd_table_retain(bootstrap_fd_t *entries) {
    arm64_fd_table_t *table = fd_table_from_entries(entries);
    if (!table) return;
    __atomic_add_fetch(
        &table->references, 1u, __ATOMIC_RELAXED);
    __atomic_add_fetch(
        &table->task_references, 1u, __ATOMIC_RELAXED);
}

static uint32_t fd_table_reference_count(bootstrap_fd_t *entries) {
    arm64_fd_table_t *table = fd_table_from_entries(entries);
    return table ? __atomic_load_n(
        &table->task_references, __ATOMIC_ACQUIRE) : 0u;
}

static void fd_table_release(bootstrap_fd_t *entries) {
    arm64_fd_table_t *table = fd_table_from_entries(entries);
    if (!table) return;
    (void)__atomic_sub_fetch(
        &table->task_references, 1u, __ATOMIC_ACQ_REL);
    if (__atomic_sub_fetch(&table->references, 1u,
                          __ATOMIC_ACQ_REL) != 0u)
        return;
    fd_table_storage_release(table);
}

static int fd_table_external_retain(bootstrap_fd_t *entries) {
    arm64_fd_table_t *table = fd_table_from_entries(entries);
    uint32_t references;

    if (!table || !__atomic_load_n(
            &table->task_references, __ATOMIC_ACQUIRE))
        return -LINUX_EBADF;
    references = __atomic_load_n(
        &table->references, __ATOMIC_ACQUIRE);
    for (;;) {
        if (!references || references == UINT32_MAX)
            return references ?
                -LINUX_EOVERFLOW : -LINUX_EBADF;
        if (__atomic_compare_exchange_n(
                &table->references, &references,
                references + 1u, 0,
                __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE))
            break;
    }
    if (!__atomic_load_n(
            &table->task_references, __ATOMIC_ACQUIRE)) {
        if (__atomic_sub_fetch(
                &table->references, 1u,
                __ATOMIC_ACQ_REL) != 0u)
            return -LINUX_EBADF;
        fd_table_storage_release(table);
        return -LINUX_EBADF;
    }
    return 0;
}

static void fd_table_external_release(bootstrap_fd_t *entries) {
    arm64_fd_table_t *table = fd_table_from_entries(entries);

    if (!table || __atomic_sub_fetch(
            &table->references, 1u,
            __ATOMIC_ACQ_REL) != 0u)
        return;
    fd_table_storage_release(table);
}

static void task_files_detach(kernel_task_t *task) {
    arm64_fd_table_t *table;
    bootstrap_fd_t *entries;
    if (!task || !task->fds) return;
    entries = task->fds;
    table = fd_table_from_entries(entries);
    if (fd_table_reference_count(entries) <= 1u)
        for (uint32_t descriptor = 0;
             descriptor < KERNEL_BOOTSTRAP_FD_MAX; ++descriptor) {
            if (fd_release(task, descriptor) >= 0)
                continue;
            if (!table || __atomic_load_n(
                    &table->slot_states[descriptor],
                    __ATOMIC_ACQUIRE) !=
                    KERNEL_FD_SLOT_RESERVED)
                continue;
            fd_cancel_constructed_descriptor(
                task, descriptor);
        }
    task->fds = 0;
    fd_table_release(entries);
}

enum {
    PIPE_WAIT_QUEUE_NONE = 0,
    PIPE_WAIT_QUEUE_READ = 1,
    PIPE_WAIT_QUEUE_WRITE = 2,
};

static void pipe_wait_remove(kernel_task_t *task);

static int task_copy(kernel_task_t *dst, const kernel_task_t *src,
                     int share_files) {
    linux_group_list_t groups;
    bootstrap_fd_t *files;
    kernel_task_scratch_t *scratch;
    kernel_task_wait_scratch_t *wait_scratch;
    const uint64_t state_offset =
        __builtin_offsetof(kernel_task_t, state);

    scratch = dst->scratch;
    wait_scratch = dst->wait_scratch;
    linux_group_list_init(&groups);
    if (linux_group_list_retain(&groups, &src->supplementary_groups) < 0)
        return -1;
    if (share_files) {
        files = src->fds;
        fd_table_retain(files);
    } else {
        files = fd_table_allocate(src->fds);
        if (!files) {
            linux_group_list_release(&groups);
            return -1;
        }
    }
    /*
     * Keep the destination invisible to the scheduler while its inherited
     * state is being copied.  Copying the parent's RUNNING state as part of
     * the structure allowed a timer interrupt to resume a half-constructed
     * child before its register frame and namespace identity were published.
     */
    task_copy_words(dst, src, state_offset);
    task_copy_words((uint8_t *)dst + state_offset + sizeof(dst->state),
                    (const uint8_t *)src + state_offset + sizeof(src->state),
                    sizeof(*dst) - state_offset - sizeof(dst->state));
    /*
     * Operation leases are address-stable ownership tokens, not inheritable
     * task state. A copied active token would make parent and child release
     * the same retained description and backing object.
     */
    bytes_zero(dst->fd_operation_leases,
               sizeof(dst->fd_operation_leases));
    dst->vector_io_requested_length = 0;
    dst->vector_io_transferred = 0;
    dst->vector_io_offset = 0;
    dst->vector_io_count = 0;
    dst->vector_io_index = 0;
    dst->vector_io_flags = 0;
    dst->vector_io_descriptor = -1;
    dst->vector_io_operation = 0;
    dst->vector_io_nonblocking = 0;
    dst->vector_io_active = 0;
    dst->vector_io_replay_frame = 0;
    task_state_set(dst, KERNEL_TASK_EMBRYO);
    if (src->futex_pi_boosted)
        dst->scheduler = src->futex_pi_base_scheduler;
    dst->futex_pi_base_scheduler = dst->scheduler;
    dst->futex_pi_boosted = 0u;
    dst->scheduler_wakeup_placed = 0;
    dst->scheduler_wait_start_us = 0u;
    dst->scheduler_wait_us = 0u;
    dst->scheduler_migrations = 0u;
    dst->scheduler_voluntary_switches = 0u;
    dst->scheduler_involuntary_switches = 0u;
    dst->scheduler_running_cpu_plus_one = 0u;
    dst->scheduler_placement_cpu_plus_one = 0u;
    dst->scheduler_accounted_cpu_plus_one = 0u;
    dst->scheduler_last_cpu_plus_one = 0u;
    dst->scheduler_voluntary_switch_pending = 0u;
    dst->futex_key = 0u;
    dst->futex_deadline_us = 0u;
    dst->futex_bitset = 0u;
    dst->futex_waitv_count = 0u;
    dst->futex_waitv_active = 0u;
    dst->futex_bucket_plus_one = 0u;
    dst->futex_previous_plus_one = 0u;
    dst->futex_next_plus_one = 0u;
    dst->group_exit_code = 0;
    dst->group_exit_signal = 0u;
    dst->group_exit_whole_group = 0u;
    __atomic_store_n(&dst->group_exit_pending, 0u, __ATOMIC_RELEASE);
    dst->pipe_wait_queue = PIPE_WAIT_QUEUE_NONE;
    dst->pipe_wait_previous_plus_one = 0;
    dst->pipe_wait_next_plus_one = 0;
    dst->scratch = scratch;
    dst->wait_scratch = wait_scratch;
    dst->fds = files;
    dst->supplementary_groups = groups;
    if (dst->exec_file_handle &&
        kernel_exec_file_retain(dst->exec_file_handle) < 0) {
        dst->exec_file_handle = KERNEL_EXEC_FILE_HANDLE_NONE;
        return -1;
    }
    edge_linux_scheduler_state_inherit(&dst->scheduler, &src->scheduler);
    edge_linux_scheduler_entity_inherit(
        &dst->scheduler_entity, &dst->scheduler,
        boottime_monotonic_us());
    return 0;
}

static void task_epoll_wait_release(kernel_task_t *task) {
    if (!task) return;
    kernel_epoll_wait_lease_release(&task->epoll_wait_lease);
}

static void task_fd_operation_lease_release(
        kernel_task_t *task, uint32_t index) {
    /*
     * A retained vector owns slot zero across every scalar segment and wake.
     * Only task_vector_io_complete() clears vector_io_active before issuing
     * the one terminal release; legacy scalar helpers and wake paths must not
     * release the shared lease between iovecs.
     */
    if (!task || index >= 2u ||
        (index == 0u && task->vector_io_active) ||
        !kernel_fd_operation_view(
            &task->fd_operation_leases[index]))
        return;
    (void)kernel_fd_operation_release(
        &task->fd_operation_leases[index]);
}

static void task_fd_operation_leases_release_all(
        kernel_task_t *task) {
    if (!task) return;
    for (uint32_t index = 0; index < 2u; ++index)
        task_fd_operation_lease_release(task, index);
}

_Static_assert(
    sizeof(((kernel_task_t *)0)->fd_operation_leases) /
            sizeof(kernel_fd_operation_lease_t) == 2u,
    "ARM64 task operation lease count changed unexpectedly");

static const bootstrap_fd_t *task_fd_operation_lease_view(
        const kernel_task_t *task, uint32_t index) {
    if (!task || index >= 2u) return 0;
    return (const bootstrap_fd_t *)kernel_fd_operation_view(
        &task->fd_operation_leases[index]);
}

static int task_fd_operation_lease_acquire_view(
        kernel_task_t *task, uint32_t index, uint64_t descriptor,
        const bootstrap_fd_t **view) {
    int result;

    if (view) *view = 0;
    if (!task || !view || index >= 2u ||
        descriptor >= KERNEL_BOOTSTRAP_FD_MAX)
        return -LINUX_EBADF;
    result = kernel_fd_operation_acquire(
        (int32_t)descriptor, &task->fd_operation_leases[index]);
    if (result < 0) return result;
    *view = task_fd_operation_lease_view(task, index);
    if (*view) return 0;
    task_fd_operation_lease_release(task, index);
    return -LINUX_EIO;
}

static void task_vector_io_state_clear(kernel_task_t *task) {
    if (!task) return;
    task->vector_io_requested_length = 0;
    task->vector_io_transferred = 0;
    task->vector_io_offset = 0;
    task->vector_io_count = 0;
    task->vector_io_index = 0;
    task->vector_io_flags = 0;
    task->vector_io_descriptor = -1;
    task->vector_io_operation = 0;
    task->vector_io_nonblocking = 0;
    task->vector_io_active = 0;
    task->vector_io_replay_frame = 0;
}

static void task_vector_io_complete(
        kernel_task_t *task, int64_t result) {
    if (!task || !task->vector_io_active) return;
    task->frame.x[0] = (uint64_t)result;
    task_vector_io_state_clear(task);
    task->fuse_wait_identity = 0;
    task_state_set(task, KERNEL_TASK_RUNNABLE);
    task_fd_operation_lease_release(task, 0);
}

static int task_vector_io_make_runnable(kernel_task_t *task) {
    if (!task || !task->vector_io_active) return 0;
    task_state_set(task, KERNEL_TASK_RUNNABLE);
    g_reschedule_target_plus_one =
        (uint16_t)((task - g_tasks) + 1u);
    return 1;
}

static void task_zero(kernel_task_t *task) {
    uint32_t cgroup_id;
    uint32_t slot;
    int was_counted;
    if (!task) return;
    was_counted = task->state != KERNEL_TASK_UNUSED &&
                  task->state != KERNEL_TASK_EMBRYO &&
                  task->state != KERNEL_TASK_ZOMBIE;
    if (g_tasks && task >= g_tasks &&
        task < g_tasks + KERNEL_BOOTSTRAP_MAX_TASKS) {
        slot = (uint32_t)(task - g_tasks);
        edge_pid_index_remove(&g_task_pid_index, task->pid, slot);
    }
    task_wait_sources_clear(task);
    task_epoll_wait_release(task);
    pipe_wait_remove(task);
    if (task->futex_bucket_plus_one || task->futex_waitv_active) {
        uint64_t futex_flags = spin_lock_irqsave(&g_futex_lock);

        kernel_futex_pi_waiter_cancel_locked(task->pid);
        futex_wait_state_clear(task);
        spin_unlock_irqrestore(&g_futex_lock, futex_flags);
    }
    /*
     * Releasing a retained descriptor backing object can synchronously
     * publish readiness. Hide the dying task from every wake scanner first.
     */
    task_state_set(task, KERNEL_TASK_EMBRYO);
    task_vector_io_state_clear(task);
    task_fd_operation_leases_release_all(task);
    kernel_exec_file_release(task->exec_file_handle);
    task->exec_file_handle = KERNEL_EXEC_FILE_HANDLE_NONE;
    if (task->pid_namespace_attached) {
        edge_pid_namespace_task_detach(task->pid);
        task->pid_namespace_attached = 0;
    }
    cgroup_id = task->cgroup_id;
    linux_group_list_release(&task->supplementary_groups);
    edge_linux_ptrace_state_reset(&task->ptrace);
    task_files_detach(task);
    task_state_set(task, KERNEL_TASK_UNUSED);
    if (g_tasks && task >= g_tasks &&
        task < g_tasks + KERNEL_BOOTSTRAP_MAX_TASKS) {
        slot = (uint32_t)(task - g_tasks);
        if (slot + 1u == g_task_high_water) {
            while (g_task_high_water &&
                   g_tasks[g_task_high_water - 1u].state ==
                       KERNEL_TASK_UNUSED)
                --g_task_high_water;
        }
    }
    if (was_counted) cgroupfs_task_leave(cgroup_id);
}

