int64_t arch_socket_buffer_execute(
    const kernel_socket_buffer_request_t *request) {
    kernel_task_t *task;
    const bootstrap_fd_t *fd;
    int lease_result;
    int64_t result;

    if (!request) return -LINUX_EIO;
    task = (kernel_task_t *)request->copy_context;
    if (!task || task != current_task()) return -LINUX_ESRCH;
    if (request->descriptor < 0)
        return -LINUX_EBADF;
    lease_result = task_fd_operation_lease_acquire_view(
        task, 0, (uint32_t)request->descriptor, &fd);
    if (lease_result < 0) return lease_result;
    if (fd->kind != KERNEL_FD_SOCKET || !fd_socket(fd)) {
        task_fd_operation_lease_release(task, 0);
        return -LINUX_ENOTSOCK;
    }
    result = request->receiving ?
        arm64_socket_buffer_receive_retained(request) :
        arm64_socket_buffer_send_retained(request);
    task_fd_operation_lease_release(task, 0);
    return result;
}

